arguments.command:
bash -lc 'set -e; python - <<"PY" 
import io,sys
p="Zend/zend_execute.h"
with open(p,"r") as f:
  s=f.read()
old="""			garbage = Z_COUNTED_P(variable_ptr);
			zend_copy_to_variable(variable_ptr, value, value_type);
			if (GC_DELREF(garbage) == 0) {
				rc_dtor_func(garbage);
			} else { /* we need to split */
				/* optimized version of GC_ZVAL_CHECK_POSSIBLE_ROOT(variable_ptr) */
				if (UNEXPECTED(GC_MAY_LEAK(garbage))) {
					gc_possible_root(garbage);
				}
			}
			return variable_ptr;"""
new="""			garbage = Z_COUNTED_P(variable_ptr);
			zend_copy_to_variable(variable_ptr, value, value_type);
			if (GC_DELREF(garbage) == 0) {
				rc_dtor_func(garbage);
				/* If we freed the old value in place, avoid returning a pointer to freed memory. */
				zval *new_ptr = emalloc(sizeof(zval));
				ZVAL_COPY_VALUE(new_ptr, value);
				return new_ptr;
			} else { /* we need to split */
				/* optimized version of GC_ZVAL_CHECK_POSSIBLE_ROOT(variable_ptr) */
				if (UNEXPECTED(GC_MAY_LEAK(garbage))) {
					gc_possible_root(garbage);
				}
			}
			return variable_ptr;"""
if old in s:
  s=s.replace(old,new)
else:
  print("Pattern not found", file=sys.stderr)
  sys.exit(1)
with open(p,"w") as f:
  f.write(s)
print("Patched")
PY'
